package com.primehr.learningdevelopment.evaluation.application;

import com.primehr.integration.administrative.PermissionDataScope;
import com.primehr.learningdevelopment.completion.domain.LdCompletionCase;
import com.primehr.learningdevelopment.completion.infrastructure.LdCompletionCaseRepository;
import com.primehr.learningdevelopment.delivery.domain.*;
import com.primehr.learningdevelopment.delivery.infrastructure.*;
import com.primehr.learningdevelopment.domain.LdEvaluationLevel;
import com.primehr.learningdevelopment.evaluation.api.LdEvaluationDtos.*;
import com.primehr.learningdevelopment.evaluation.domain.*;
import com.primehr.learningdevelopment.evaluation.infrastructure.*;
import com.primehr.learningdevelopment.infrastructure.LdEvaluationLevelRepository;
import com.primehr.shared.audit.PrimeHrAuditService;
import com.primehr.shared.exception.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;

@Service @Transactional
public class LdEvaluationServiceImpl implements LdEvaluationService {
 private static final String FEED_VERSION="1.0";
 private final LdEvaluationTaskRepository tasks;private final LdEvaluationResultRepository results;private final LdLearningActionPlanRepository laps;private final LdCompletionCaseRepository completions;private final LdOfferingRepository offerings;private final LdProgramRepository programs;private final LdEvaluationLevelRepository levels;private final PrimeHrAuditService audit;private final int minimumAggregateCohort;
 public LdEvaluationServiceImpl(LdEvaluationTaskRepository tasks,LdEvaluationResultRepository results,LdLearningActionPlanRepository laps,LdCompletionCaseRepository completions,LdOfferingRepository offerings,LdProgramRepository programs,LdEvaluationLevelRepository levels,PrimeHrAuditService audit,@Value("${primehr.reporting.minimum-aggregate-cohort:5}")int minimumAggregateCohort){this.tasks=tasks;this.results=results;this.laps=laps;this.completions=completions;this.offerings=offerings;this.programs=programs;this.levels=levels;this.audit=audit;if(minimumAggregateCohort<2)throw new IllegalArgumentException("minimum aggregate cohort must be at least 2");this.minimumAggregateCohort=minimumAggregateCohort;}
 @Override @Transactional(readOnly=true) public List<TaskResponse>tasks(String a,String actor,PermissionDataScope scope){return tasks.findByAgencyIdOrderByDueDateAsc(a).stream().filter(x->visible(x,actor,scope)).map(x->task(a,x)).toList();}
 @Override @Transactional(readOnly=true) public List<TaskResponse>mine(String a,String actor){return tasks.findByAgencyIdAndEmployeeNoIgnoreCaseOrderByDueDateAsc(a,actor).stream().map(x->task(a,x)).toList();}
 @Override @Transactional(readOnly=true) public List<TaskResponse>assigned(String a,String actor){return tasks.findByAgencyIdAndAssignedEvaluatorNoIgnoreCaseOrderByDueDateAsc(a,actor).stream().map(x->task(a,x)).toList();}
 @Override public List<TaskResponse>initialize(String a,String completionId,InitializeInput in,String actor,PermissionDataScope scope,String correlation){if(scope==PermissionDataScope.OWN_RECORDS)throw new AccessDeniedException("Evaluation initialization requires Assigned Records or Agency Wide scope");LdCompletionCase completion=completion(a,completionId);check(completion.getVersion(),in.completionRecordVersion());if(completion.getStatus()!=LdCompletionCase.Status.COMPLETED)throw new IllegalStateException("Only a verified COMPLETED case may be evaluated");if(tasks.existsByAgencyIdAndCompletionCaseId(a,completionId))throw new OptimisticConflictException("Evaluation tasks already exist for this completion");LdOffering offering=offering(a,completion.getOfferingId());assignedProgramAccess(a,offering,actor,scope);if(offering.getOfferingVersion()!=completion.getOfferingVersion())throw new IllegalStateException("Offering evaluation snapshot is inconsistent");List<LdEvaluationLevel> definitions=levels.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrderAsc(a,offering.getEvaluationFrameworkVersionId());if(definitions.isEmpty())throw new IllegalStateException("Offering evaluation framework has no levels");for(LdEvaluationLevel level:definitions){var role=role(level.getLevelType());String evaluator=switch(role){case PARTICIPANT->completion.getEmployeeNo();case SUPERVISOR->required(in.supervisorEmployeeNo(),"supervisorEmployeeNo");case LD_STAFF->required(in.staffEvaluatorEmployeeNo(),"staffEvaluatorEmployeeNo");};tasks.save(new LdEvaluationTask(a,completionId,offering.getId(),completion.getEmployeeNo(),offering.getEvaluationFrameworkVersionId(),offering.getEvaluationFingerprint(),level,role,evaluator,completion.getCompletionDate()));}tasks.flush();List<TaskResponse>out=tasks.findByAgencyIdAndCompletionCaseIdOrderByDueDateAsc(a,completionId).stream().map(x->task(a,x)).toList();audit.record(a,"INITIALIZE_LD_EVALUATION_TASKS","LD_COMPLETION_CASE",completionId,completion.getContentRevision(),completion.getVersion(),null,out,null,correlation);return out;}
 @Override public ResultResponse submitResult(String a,String taskId,ResultInput in,String actor,String correlation){LdEvaluationTask task=taskEntity(a,taskId);check(task.getVersion(),in.taskRecordVersion());if(task.getStatus()!=LdEvaluationTask.Status.OPEN)throw new IllegalStateException("Evaluation task is already satisfied");if(!task.getAssignedEvaluatorNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the assigned evaluator may submit this result");validate(task,in);List<LdEvaluationResult> prior=results.findByAgencyIdAndTaskIdOrderByResultRevisionDesc(a,taskId);if(!prior.isEmpty()&&prior.get(0).getStatus()!=LdEvaluationResult.Status.RETURNED)throw new IllegalStateException("The current result must be returned before a new revision is submitted");int revision=prior.isEmpty()?1:prior.get(0).getResultRevision()+1;String predecessor=prior.isEmpty()?null:prior.get(0).getId();Boolean passed=passed(task,in);String fp=sha(task.getId()+"|"+revision+"|"+in.score()+"|"+passed+"|"+in.narrative()+"|"+in.evidenceReference());LdEvaluationResult value=results.saveAndFlush(new LdEvaluationResult(a,taskId,revision,predecessor,in.score(),passed,in.narrative(),in.evidenceReference(),actor,Instant.now(),fp));ResultResponse out=result(value);audit.record(a,"SUBMIT_LD_EVALUATION_RESULT","LD_EVALUATION_RESULT",value.getId(),revision,value.getVersion(),null,out,null,correlation);return out;}
 @Override public TaskResponse decideResult(String a,String taskId,String resultId,DecisionInput in,String actor,PermissionDataScope scope,String correlation){LdEvaluationTask task=taskEntity(a,taskId);assignedProgramAccess(a,offering(a,task.getOfferingId()),actor,scope);check(task.getVersion(),in.taskRecordVersion());LdEvaluationResult value=resultEntity(a,resultId);if(!value.getTaskId().equals(taskId))throw new ResourceNotFoundException("Evaluation result not found for task");check(value.getVersion(),in.resultRecordVersion());TaskResponse before=task(a,task);value.decide(in.approve(),in.reason(),actor,Instant.now());results.saveAndFlush(value);if(in.approve())task.satisfy(value.getId());else task.reopen();task=tasks.saveAndFlush(task);TaskResponse out=task(a,task);audit.record(a,in.approve()?"VERIFY_LD_EVALUATION_RESULT":"RETURN_LD_EVALUATION_RESULT","LD_EVALUATION_TASK",taskId,null,task.getVersion(),before,out,in.reason(),correlation);return out;}
 @Override @Transactional(readOnly=true) public List<LapResponse>actionPlans(String a,String actor,PermissionDataScope scope){return laps.findByAgencyIdOrderByTargetDateAsc(a).stream().filter(x->scope==PermissionDataScope.AGENCY_WIDE||x.getEmployeeNo().equalsIgnoreCase(actor)||x.getSupervisorEmployeeNo().equalsIgnoreCase(actor)).map(this::lap).toList();}
 @Override @Transactional(readOnly=true) public List<LapResponse>myActionPlans(String a,String actor){return laps.findByAgencyIdAndEmployeeNoIgnoreCaseOrderByTargetDateAsc(a,actor).stream().map(this::lap).toList();}
 @Override @Transactional(readOnly=true) public List<LapResponse>assignedActionPlans(String a,String actor){return laps.findByAgencyIdAndSupervisorEmployeeNoIgnoreCaseOrderByTargetDateAsc(a,actor).stream().map(this::lap).toList();}
 @Override public LapResponse createActionPlan(String a,String completionId,LapInput in,String actor,PermissionDataScope scope,String correlation){LdCompletionCase c=completion(a,completionId);check(c.getVersion(),in.completionRecordVersion());if(c.getStatus()!=LdCompletionCase.Status.COMPLETED)throw new IllegalStateException("Action plans require a verified COMPLETED case");if(!c.getEmployeeNo().equalsIgnoreCase(actor)&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Action plan is outside allowed scope");if(in.targetDate().isBefore(c.getCompletionDate()))throw new IllegalArgumentException("targetDate cannot precede completionDate");laps.findByAgencyIdAndCompletionCaseId(a,completionId).ifPresent(x->{throw new OptimisticConflictException("An action plan already exists for this completion");});LdLearningActionPlan value=laps.saveAndFlush(new LdLearningActionPlan(a,completionId,c.getEmployeeNo(),in.supervisorEmployeeNo(),in.applicationObjective(),in.successMeasure(),in.targetDate()));LapResponse out=lap(value);audit.record(a,"CREATE_LD_LEARNING_ACTION_PLAN","LD_LEARNING_ACTION_PLAN",value.getId(),value.getContentRevision(),value.getVersion(),null,out,null,correlation);return out;}
 @Override public LapResponse updateActionPlan(String a,String id,LapUpdate in,String actor,PermissionDataScope scope,String correlation){LdLearningActionPlan value=lapEntity(a,id);ownOrAgency(value,actor,scope);check(value.getVersion(),in.recordVersion());LdCompletionCase completion=completion(a,value.getCompletionCaseId());if(in.targetDate().isBefore(completion.getCompletionDate()))throw new IllegalArgumentException("targetDate cannot precede completionDate");LapResponse before=lap(value);value.update(in.applicationObjective(),in.successMeasure(),in.targetDate());value=laps.saveAndFlush(value);return lapChanged(a,value,"UPDATE_LD_LEARNING_ACTION_PLAN",before,null,correlation);}
 @Override public LapResponse submitActionPlan(String a,String id,Transition in,String actor,String correlation){LdLearningActionPlan value=lapEntity(a,id);if(!value.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the participant may submit the action plan");check(value.getVersion(),in.recordVersion());LapResponse before=lap(value);value.submit(actor,Instant.now());value=laps.saveAndFlush(value);return lapChanged(a,value,"SUBMIT_LD_LEARNING_ACTION_PLAN",before,in.reason(),correlation);}
 @Override public LapResponse followUp(String a,String id,FollowUpInput in,String actor,PermissionDataScope scope,String correlation){LdLearningActionPlan value=lapEntity(a,id);if(scope!=PermissionDataScope.AGENCY_WIDE&&!value.getSupervisorEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the assigned supervisor may record follow-through");check(value.getVersion(),in.recordVersion());if(LocalDate.now().isBefore(value.getTargetDate()))throw new IllegalStateException("Follow-through cannot be finalized before the target date");LapResponse before=lap(value);value.followUp(in.approve(),in.outcome(),in.evidenceReference(),in.reason(),actor,Instant.now());value=laps.saveAndFlush(value);return lapChanged(a,value,in.approve()?"VERIFY_LD_LEARNING_ACTION_PLAN":"RETURN_LD_LEARNING_ACTION_PLAN",before,in.reason(),correlation);}
 @Override @Transactional(readOnly=true) public EffectivenessResponse effectiveness(String a,String actor,String correlation){List<LdEvaluationResult> verified=results.findByAgencyIdAndStatus(a,LdEvaluationResult.Status.VERIFIED);Map<String,LdEvaluationTask> taskMap=tasks.findByAgencyIdOrderByDueDateAsc(a).stream().collect(Collectors.toMap(LdEvaluationTask::getId,Function.identity()));Map<String,LdOffering> offeringMap=offerings.findByAgencyIdOrderByCreatedAtDesc(a).stream().collect(Collectors.toMap(LdOffering::getId,Function.identity()));Map<String,LdProgram> programMap=programs.findByAgencyIdOrderByCreatedAtDesc(a).stream().collect(Collectors.toMap(LdProgram::getId,Function.identity()));List<EffectivenessRow> rows=new ArrayList<>();int suppressed=0;suppressed+=aggregate(rows,"OFFERING",verified,taskMap,r->{LdEvaluationTask t=taskMap.get(r.getTaskId());return t==null?null:t.getOfferingId();},id->{LdOffering o=offeringMap.get(id);return o==null?id:o.getTitle();});suppressed+=aggregate(rows,"PROVIDER",verified,taskMap,r->{LdEvaluationTask t=taskMap.get(r.getTaskId());LdOffering o=t==null?null:offeringMap.get(t.getOfferingId());return o==null?null:o.getProviderId();},id->offeringMap.values().stream().filter(o->id.equals(o.getProviderId())).map(LdOffering::getProviderName).filter(Objects::nonNull).findFirst().orElse(id));suppressed+=aggregate(rows,"INTERVENTION",verified,taskMap,r->{LdEvaluationTask t=taskMap.get(r.getTaskId());LdOffering o=t==null?null:offeringMap.get(t.getOfferingId());LdProgram p=o==null?null:programMap.get(o.getProgramId());return p==null?null:p.getInterventionVersionId();},id->id);EffectivenessResponse out=new EffectivenessResponse(Instant.now(),minimumAggregateCohort,suppressed,List.copyOf(rows));audit.record(a,"VIEW_LD_EFFECTIVENESS","LD_EFFECTIVENESS",a,null,null,null,Map.of("requestedBy",actor,"rowCount",rows.size(),"suppressedGroups",suppressed,"minimumCohort",minimumAggregateCohort),null,correlation);return out;}
 @Override @Transactional(readOnly=true) public HrmReviewPacket hrmReviewPacket(String a,String completionId,String actor,PermissionDataScope scope,String correlation){LdCompletionCase c=completion(a,completionId);LdOffering o=offering(a,c.getOfferingId());if(scope!=PermissionDataScope.AGENCY_WIDE&&!program(a,o.getProgramId()).getAccountableEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("HRM review packet is outside assigned scope");List<TaskResponse> evaluation=tasks.findByAgencyIdAndCompletionCaseIdOrderByDueDateAsc(a,completionId).stream().map(x->task(a,x)).toList();LapResponse plan=laps.findByAgencyIdAndCompletionCaseId(a,completionId).map(this::lap).orElse(null);HrmReviewPacket out=new HrmReviewPacket(c.getId(),c.getEmployeeNo(),c.getEmployeeName(),c.getOfferingId(),c.getCreditedHours(),c.getCompletionDate(),c.getCompletionFingerprint(),evaluation,plan);audit.record(a,"VIEW_LD_HRM_REVIEW_PACKET","LD_COMPLETION_CASE",completionId,c.getContentRevision(),c.getVersion(),null,Map.of("requestedBy",actor,"evaluationCount",evaluation.size(),"hasActionPlan",plan!=null),null,correlation);return out;}
 @Override @Transactional(readOnly=true) public CompletionFeedPage completionFeed(String a,Instant after,Instant through,int page,int size,String actor,String correlation){if(after==null||through==null||!through.isAfter(after))throw new IllegalArgumentException("changedThrough must be after changedAfter");if(page<0||size<1||size>500)throw new IllegalArgumentException("page must be non-negative and size must be between 1 and 500");List<LdCompletionCase> eligible=completions.findByAgencyIdOrderByCreatedAtDesc(a).stream().filter(x->x.getStatus()==LdCompletionCase.Status.COMPLETED).filter(x->x.getUpdatedAt().isAfter(after)&&!x.getUpdatedAt().isAfter(through)).sorted(Comparator.comparing(LdCompletionCase::getUpdatedAt).thenComparing(LdCompletionCase::getId)).toList();int from=Math.min(page*size,eligible.size()),to=Math.min(from+size,eligible.size());List<CompletionFeedItem> content=eligible.subList(from,to).stream().map(x->feed(a,x)).toList();CompletionFeedPage out=new CompletionFeedPage(FEED_VERSION,after,through,Instant.now(),page,size,eligible.size(),eligible.isEmpty()?0:(eligible.size()+size-1)/size,content);audit.record(a,"PULL_LD_COMPLETION_OUTCOMES","LD_COMPLETION_FEED",a,null,null,null,Map.of("requestedBy",actor,"schemaVersion",FEED_VERSION,"changedAfter",after.toString(),"changedThrough",through.toString(),"page",page,"size",size,"resultCount",content.size()),null,correlation);return out;}
 private CompletionFeedItem feed(String a,LdCompletionCase c){LdOffering o=offering(a,c.getOfferingId());LdProgram p=program(a,o.getProgramId());String fp=sha(c.getId()+"|"+c.getVersion()+"|"+c.getCompletionFingerprint()+"|"+o.getProgramFingerprint()+"|"+o.getProviderFingerprint());return new CompletionFeedItem(c.getId(),c.getVersion(),c.getEmployeeNo(),o.getId(),o.getOfferingVersion(),o.getCode(),o.getTitle(),p.getId(),p.getProgramVersion(),p.getInterventionVersionId(),o.getProviderId(),o.getProviderName(),c.getCreditedHours(),c.getCompletionDate(),c.getVerifiedAt(),c.getCompletionFingerprint(),c.getUpdatedAt(),fp);}
 private int aggregate(List<EffectivenessRow> out,String dimension,List<LdEvaluationResult> values,Map<String,LdEvaluationTask> taskMap,Function<LdEvaluationResult,String> key,Function<String,String> label){int suppressed=0;for(var entry:values.stream().filter(value->key.apply(value)!=null).collect(Collectors.groupingBy(key)).entrySet()){String id=entry.getKey();List<LdEvaluationResult> group=entry.getValue();long employees=group.stream().map(value->taskMap.get(value.getTaskId())).filter(Objects::nonNull).map(LdEvaluationTask::getEmployeeNo).filter(Objects::nonNull).map(value->value.toUpperCase(Locale.ROOT)).distinct().count();if(employees<minimumAggregateCohort){suppressed++;continue;}long passed=group.stream().filter(x->Boolean.TRUE.equals(x.getPassed())).count();List<BigDecimal> scores=group.stream().map(LdEvaluationResult::getScore).filter(Objects::nonNull).toList();BigDecimal average=scores.isEmpty()?null:scores.stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(scores.size()),6,RoundingMode.HALF_UP);out.add(new EffectivenessRow(dimension,id,label.apply(id),group.size(),passed,average));}return suppressed;}
 private static LdEvaluationTask.EvaluatorRole role(LdEvaluationLevel.Type type){return switch(type){case REACTION,LEARNING->LdEvaluationTask.EvaluatorRole.PARTICIPANT;case BEHAVIOR_APPLICATION->LdEvaluationTask.EvaluatorRole.SUPERVISOR;case RESULTS,RETURN_OF_EXPECTATION->LdEvaluationTask.EvaluatorRole.LD_STAFF;};}
 private static void validate(LdEvaluationTask task,ResultInput in){switch(task.getScoreMethod()){case QUALITATIVE->{if(in.score()!=null||in.passed()!=null)throw new IllegalArgumentException("Qualitative results must not supply score or passed");}case PASS_FAIL->{if(in.score()!=null||in.passed()==null)throw new IllegalArgumentException("Pass/fail results require passed and no score");}case PERCENTAGE->{if(in.score()==null||in.score().compareTo(BigDecimal.valueOf(100))>0)throw new IllegalArgumentException("Percentage score must be between 0 and 100");}case POINTS->{if(in.score()==null)throw new IllegalArgumentException("Points score is required");}}}
 private static Boolean passed(LdEvaluationTask task,ResultInput in){return switch(task.getScoreMethod()){case QUALITATIVE->null;case PASS_FAIL->in.passed();case PERCENTAGE,POINTS->in.score().compareTo(task.getPassingScore())>=0;};}
 private boolean visible(LdEvaluationTask t,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||t.getEmployeeNo().equalsIgnoreCase(actor)||t.getAssignedEvaluatorNo().equalsIgnoreCase(actor);}
 private static void ownOrAgency(LdLearningActionPlan p,String actor,PermissionDataScope scope){if(!p.getEmployeeNo().equalsIgnoreCase(actor)&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Action plan is outside allowed scope");}
 private TaskResponse task(String a,LdEvaluationTask x){return new TaskResponse(x.getId(),x.getVersion(),x.getCompletionCaseId(),x.getOfferingId(),x.getEmployeeNo(),x.getFrameworkVersionId(),x.getFrameworkFingerprint(),x.getLevelType().name(),x.isRequired(),x.getScoreMethod().name(),x.getPassingScore(),x.getEvidenceRequirements(),x.getInstrumentGuidance(),x.getEvaluatorRole().name(),x.getAssignedEvaluatorNo(),x.getDueDate(),x.getStatus().name(),x.getCurrentResultId(),results.findByAgencyIdAndTaskIdOrderByResultRevisionDesc(a,x.getId()).stream().map(this::result).toList());}
 private ResultResponse result(LdEvaluationResult x){return new ResultResponse(x.getId(),x.getVersion(),x.getResultRevision(),x.getSupersedesResultId(),x.getScore(),x.getPassed(),x.getNarrative(),x.getEvidenceReference(),x.getStatus().name(),x.getSubmittedBy(),x.getSubmittedAt(),x.getDecidedBy(),x.getDecidedAt(),x.getDecisionReason(),x.getResultFingerprint());}
 private LapResponse lap(LdLearningActionPlan x){return new LapResponse(x.getId(),x.getVersion(),x.getCompletionCaseId(),x.getEmployeeNo(),x.getSupervisorEmployeeNo(),x.getApplicationObjective(),x.getSuccessMeasure(),x.getTargetDate(),x.getStatus().name(),x.getContentRevision(),x.getSubmittedBy(),x.getSubmittedAt(),x.getFollowUpOutcome(),x.getEvidenceReference(),x.getDecidedBy(),x.getDecidedAt(),x.getDecisionReason());}
 private LapResponse lapChanged(String a,LdLearningActionPlan x,String action,LapResponse before,String reason,String correlation){LapResponse out=lap(x);audit.record(a,action,"LD_LEARNING_ACTION_PLAN",x.getId(),x.getContentRevision(),x.getVersion(),before,out,reason,correlation);return out;}
 private LdCompletionCase completion(String a,String id){return completions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D completion case not found"));}private LdOffering offering(String a,String id){return offerings.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D offering not found"));}private LdProgram program(String a,String id){return programs.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D program not found"));}private LdEvaluationTask taskEntity(String a,String id){return tasks.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D evaluation task not found"));}private LdEvaluationResult resultEntity(String a,String id){return results.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D evaluation result not found"));}private LdLearningActionPlan lapEntity(String a,String id){return laps.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D action plan not found"));}
 private void assignedProgramAccess(String a,LdOffering offering,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.OWN_RECORDS)throw new AccessDeniedException("Operation requires Assigned Records or Agency Wide scope");if(scope==PermissionDataScope.ASSIGNED_RECORDS&&!program(a,offering.getProgramId()).getAccountableEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Evaluation is outside assigned program scope");}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}private static String required(String value,String name){if(value==null||value.isBlank())throw new IllegalArgumentException(name+" is required for configured evaluation levels");return value.trim();}private static String sha(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
